            if(this.whiteSet.contains(userName)) {
                // access is granted for the user
                return true;
            }
            if(this.whiteSet.contains(groupName)) {
                // access is granted for the group
                return true;
            }

            log.error("An unauthorised user tried to talk to me: " + userName);
            return false;
        }
        // no whitelist
        return true;

    }

