     * scope or the optional flag.
     *
     * @param dependency
     * @return
     */
    @VisibleForTesting
    static String getKey(Dependency dependency) {
        return dependency.getGroupId()
                + ":"
                + dependency.getArtifactId()
                + ":"
                + dependency.getVersion()
                + ":"
