                    }
                    var outputString = this.generateOutputString(inputFile);
                    Files.writeString(outputFile.toPath(), outputString);
                }
                return 0;
            } else {
                LOG.info("Input file is not an APK.");
                return 1;
            }
        } else {
            LOG.info("Input file does not exist.");
