        StringBuffer field = new StringBuffer();
        for (int i = 0; i < columns.length; i++) {
            field.append(String.format(fields, columns[i]));
            if (i < columns.length - 1) {
                field.append(",");
            }
        }
        return String.format(temp, tableName, field.toString());
    }

