                } else if (args.length == 2) {
                    setBedrockBackend(args);
                } else {
                    instance.sendMessage(sender, localization.get(locale, "usage.setgeyserbackend"));
                }
                break;
            }
            default: {
                showHelp();
            }
        }
    }


