				if (c.length == 1){
					this.blackLeftCastleAllowed = false;
					this.blackRightCastleAllowed = false;
				}
			} else if (String.valueOf(c[i]).equals("-")){
				this.blackLeftCastleAllowed = false;
				this.blackRightCastleAllowed = false;
			} else {
				String d = String.valueOf(c[i]);
				if (d.equals("Q")) this.whiteLeftCastleAllowed = true;
