                TransformationMappings mappings = getTransformationMappings(
                    transformationMap,
                    allFields,
                    transformationAnnotation.property());

                mappings.transformations.add(
                    getTransformationField(
                        field,
                        transformationAnnotation));
            }
        }
        return transformationMap;
    }

