     *
     * @param cacheKey 缓存的KEY
     * @return
     */
    private Object getCacheInfo(String cacheKey) {
        Object result = cache.get(String.format(cacheKey, OK));
        if (result == null) {
            result = cache.get(String.format(cacheKey, FAIL));
        }
        return result;
    }

