        if (this.rateLimiterRegistry == null) return;
        RateLimiter rateLimiter = rateLimiterRegistry.rateLimiter(getCombineKey(point));
        if (!rateLimiter.acquirePermission()) throw new ChatApiRequestTooManyBizException();
    }

