            long truncated = counter.getTruncated().incrementAndGet();
            if (fetcherConfig.getMaxFilesTruncated() > -1 &&
                    truncated >= fetcherConfig.getMaxFilesTruncated()) {
                LOGGER.info("hit max truncated files");
                return false;
            }
