                new FetchKey("", record.getFilename(), record.getOffset(),
                        record.getOffset() + record.getLength() - 1), new EmitKey());
        byte[] warcRecordGZBytes;
        try {
            warcRecordGZBytes = fetchWarcBytes(t);
