                LOGGER.warn("problem writing id={}", id, e);
            }
        } finally {
            try {
                Files.delete(tmp);
            } catch (IOException e) {
                LOGGER.warn("can't delete " + tmp.toAbsolutePath(), e);
            }
        }
    }

