        if (exprList != null) {
            for (int i = 0; i < exprList.size(); i++) {
                Log.i(TAG, "[updateManager] exprUrl " + exprList.get(i).videoURL);
            }
        }
        if (newList != null) {
            for (int i = 0; i < newList.size(); i++) {
                Log.i(TAG, "[updateManager] newUrl " + newList.get(i).videoURL);
