            buffer.flip();
            int size = buffer.array().length;
            byte[] temp = new byte[requestBytes.length + size];
            System.arraycopy(requestBytes, 0, temp, 0, requestBytes.length);
            System.arraycopy(buffer.array(), 0, temp, requestBytes.length, size);
            requestBytes = temp;
            buffer.clear();
